-- ================================================================
-- 042. Вернуть букетам служебные данные, стёртые сохранением в админке.
--
-- До исправления (коммит aebddad, 12.11.2026) кнопка «Сохранить» в админке
-- заменяла attributes букета только размерами и составом. 11–12 ноября так
-- сохранили 15 букетов, и у них пропали прежние названия до миграции 040
-- (attributes.beforeRename — для отката) и данные импорта из Telegram
-- (postId, source, publishedAt, priceFromChannel, note).
--
-- Здесь они дописываются обратно из выгрузки 10.11.2026 — только
-- недостающие ключи: всё, что есть в букете сейчас (состав, размеры,
-- правки владельца), остаётся как есть. Название, цена, наличие, видимость
-- не меняются. Только данные.
-- ================================================================
begin;

create temp table _restore_042 (
  id uuid primary key,
  meta jsonb not null,
  before_rename jsonb not null
) on commit drop;


create temp table _snapshot_042 on commit drop as
  select id, name, price, is_active, availability_mode, nickname,
         attributes->'composition' as composition, attributes->'sizes' as sizes
  from products where id in (select id from _restore_042);

update products p
set attributes = r.meta
      || coalesce(p.attributes, '{}'::jsonb)
      || case when coalesce(p.attributes, '{}'::jsonb) ? 'beforeRename' then '{}'::jsonb
              else jsonb_build_object('beforeRename', r.before_rename) end
from _restore_042 r
where p.id = r.id
  and (not coalesce(p.attributes, '{}'::jsonb) ? 'beforeRename'
       or not coalesce(p.attributes, '{}'::jsonb) @> r.meta);

do $$
declare
  v_n int;
begin
  select count(*) into v_n from products p join _restore_042 r on r.id = p.id where not p.attributes ? 'beforeRename';
  if v_n > 0 then raise exception 'У % букетов нет прежнего названия', v_n; end if;

  select count(*) into v_n from products p join _snapshot_042 s on s.id = p.id
  where p.name is distinct from s.name or p.price is distinct from s.price or p.is_active is distinct from s.is_active
     or p.availability_mode is distinct from s.availability_mode or p.nickname is distinct from s.nickname
     or p.attributes->'composition' is distinct from s.composition or p.attributes->'sizes' is distinct from s.sizes;
  if v_n > 0 then raise exception 'Задето лишнее у % букетов', v_n; end if;

  raise notice 'Прежние названия есть у всех % букетов, остальное не тронуто', (select count(*) from _restore_042);
end $$;

commit;
